<?php
require __DIR__.'/bootstrap.php';$page=$_GET['p']??'dashboard';$err='';$msg='';
if($page==='branch-switch'&&$_SERVER['REQUEST_METHOD']==='POST'){need_login();check_token();$q=$pdo->prepare("SELECT id FROM branches WHERE id=? AND workspace_id=? AND status='active'");$q->execute([(int)($_POST['branch_id']??0),$wid=(int)$_SESSION['u']['workspace_id']]);if($q->fetchColumn()){$_SESSION['branch_id']=(int)$_POST['branch_id'];header('Location: index.php');exit;}http_response_code(403);exit('فرع غير صالح.');}\nif($page==='logout'){$_SESSION=[];session_destroy();header('Location: index.php?p=login');exit;}
if($page==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){check_token();$ip='attempts';$_SESSION[$ip]=$_SESSION[$ip]??0;if($_SESSION[$ip]>=8)$err='محاولات كثيرة، أعد المحاولة لاحقاً.';else{$q=$pdo->prepare("SELECT u.*,w.name workspace_name FROM users u JOIN workspaces w ON w.id=u.workspace_id WHERE u.username=? AND u.status='active' LIMIT 1");$q->execute([trim($_POST['username']??'')]);$u=$q->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);unset($u['password_hash']);$_SESSION['u']=$u;$_SESSION[$ip]=0;$pdo->prepare('UPDATE users SET last_login=NOW() WHERE id=?')->execute([$u['id']]);header('Location: index.php');exit;}$_SESSION[$ip]++;$err='اسم المستخدم أو كلمة المرور غير صحيحة.';}}
if($page!=='login')need_login();
$u=$_SESSION['u']??null;$wid=(int)($u['workspace_id']??0);$bid=(int)($_SESSION['branch_id']??$u['branch_id']??0);
if($page==='products'&&$_SERVER['REQUEST_METHOD']==='POST'){check_token();if(!manager()){$err='لا تملك صلاحية إضافة المنتجات.';}else{try{$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO products(workspace_id,name,sku,barcode,cost,price,alert_qty) VALUES(?,?,?,?,?,?,?)');$q->execute([$wid,trim($_POST['name']),trim($_POST['sku']??'')?:null,trim($_POST['barcode']??'')?:null,max(0,(float)$_POST['cost']),max(0,(float)$_POST['price']),max(0,(float)$_POST['alert_qty'])]);$pid=(int)$pdo->lastInsertId();$qty=max(0,(float)$_POST['qty']);$pdo->prepare('INSERT INTO inventory(workspace_id,branch_id,product_id,quantity) VALUES(?,?,?,?)')->execute([$wid,$bid,$pid,$qty]);if($qty>0)$pdo->prepare("INSERT INTO inventory_movements(workspace_id,branch_id,product_id,user_id,movement_type,quantity,note) VALUES(?,?,?,?,'opening',?,'رصيد افتتاحي')")->execute([$wid,$bid,$pid,$u['id'],$qty]);audit_event($pdo,'product.create','product',$pid);$pdo->commit();$msg='تمت إضافة المنتج بنجاح.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err='تعذر الحفظ؛ تحقق من عدم تكرار SKU أو الباركود.';}}}
if($page==='pos'&&$_SERVER['REQUEST_METHOD']==='POST'){check_token();try{$ids=$_POST['pid']??[];$qtys=$_POST['qty']??[];if(!$ids||count($ids)>80)throw new Exception('السلة فارغة.');$pdo->beginTransaction();$items=[];$sub=0;foreach($ids as $i=>$id){$qty=(float)($qtys[$i]??0);if($qty<=0)continue;$q=$pdo->prepare('SELECT p.*,i.quantity stock FROM products p JOIN inventory i ON i.product_id=p.id AND i.branch_id=? WHERE p.id=? AND p.workspace_id=? AND p.is_active=1 FOR UPDATE');$q->execute([$bid,(int)$id,$wid]);$p=$q->fetch();if(!$p||$p['stock']<$qty)throw new Exception('المنتج غير متاح أو المخزون غير كافٍ.');$line=$qty*$p['price'];$sub+=$line;$items[]=[$p,$qty,$line];}if(!$items)throw new Exception('أدخل كمية صحيحة.');$discount=max(0,(float)($_POST['discount']??0));if($discount>$sub)throw new Exception('الخصم أكبر من الإجمالي.');$total=$sub-$discount;$invoice='R-'.date('ymdHis').'-'.random_int(10,99);$q=$pdo->prepare('INSERT INTO sales(workspace_id,branch_id,invoice_no,cashier_id,subtotal,discount,total,paid,payment_method) VALUES(?,?,?,?,?,?,?,?,?)');$method=in_array($_POST['method']??'cash',['cash','card','transfer'],true)?$_POST['method']:'cash';$q->execute([$wid,$bid,$invoice,$u['id'],$sub,$discount,$total,$total,$method]);$sid=(int)$pdo->lastInsertId();foreach($items as [$p,$qty,$line]){$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,product_name,quantity,unit_price,unit_cost,line_total) VALUES(?,?,?,?,?,?,?)')->execute([$sid,$p['id'],$p['name'],$qty,$p['price'],$p['cost'],$line]);$pdo->prepare('UPDATE inventory SET quantity=quantity-? WHERE branch_id=? AND product_id=?')->execute([$qty,$bid,$p['id']]);$pdo->prepare("INSERT INTO inventory_movements(workspace_id,branch_id,product_id,user_id,movement_type,quantity,reference_id,note) VALUES(?,?,?,?,'sale',?,?,?)")->execute([$wid,$bid,$p['id'],$u['id'],-$qty,$sid,'بيع نقطة البيع']);}audit_event($pdo,'sale.create','sale',$sid);$pdo->commit();$msg="تم إصدار الفاتورة {$invoice} بإجمالي ".cash($total);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}}
function start_page($title){global $u;?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#087f8c"><link rel="manifest" href="manifest.webmanifest"><link rel="stylesheet" href="assets/app.css"><title><?=h($title)?> | ALREDFANI RETAIL ERP</title></head><body><header><a class="logo" href="index.php">ALREDFANI <small>RETAIL ERP</small></a><nav><a href="index.php">الرئيسية</a><a href="index.php?p=pos">نقطة البيع</a><a href="index.php?p=products">المنتجات</a><a href="index.php?p=sales">المبيعات</a><a href="index.php?p=inventory">المخزون</a><a href="index.php?p=reports">التقارير</a><a href="index.php?p=logout">خروج</a></nav><span><?=h($u['name']??'')?></span></header><main class="wrap"><h1><?=h($title)?></h1><?php }
function end_page(){?></main><footer>ALREDFANI RETAIL ERP</footer><script src="assets/app.js"></script></body></html><?php }
if($page==='login'){?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/app.css"><body class="center"><form class="card narrow" method="post"><h1>تسجيل الدخول</h1><?php if($err):?><div class="alert bad"><?=h($err)?></div><?php endif;?><input type="hidden" name="_token" value="<?=h(token())?>"><label>اسم المستخدم<input name="username" required></label><label>كلمة المرور<input type="password" name="password" required></label><button class="btn">دخول</button><p class="muted">التثبيت الأولي عبر install.php</p></form></body></html><?php exit;}
if($page==='dashboard'){ $q=$pdo->prepare("SELECT COALESCE(SUM(total),0) FROM sales WHERE workspace_id=? AND branch_id=? AND status='completed' AND DATE(created_at)=CURDATE()");$q->execute([$wid,$bid]);$today=$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM products WHERE workspace_id=? AND is_active=1');$q->execute([$wid]);$pc=$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM inventory WHERE workspace_id=? AND branch_id=? AND quantity<=0');$q->execute([$wid,$bid]);$low=$q->fetchColumn();start_page('لوحة التحكم');?><section class="hero"><div><p>مساحة العمل: <?=h($u['workspace_name'])?></p><h2>مرحباً <?=h($u['name'])?></h2><p>إدارة المبيعات والمخزون والفروع من واجهة واحدة.</p></div><a class="btn pale" href="index.php?p=pos">＋ فاتورة جديدة</a></section><section class="stats"><article><span>مبيعات اليوم</span><b><?=cash($today)?></b></article><article><span>المنتجات</span><b><?=$pc?></b></article><article><span>أصناف نفد مخزونها</span><b><?=$low?></b></article></section><section class="card"><h2>الوصول السريع</h2><div class="links"><a href="index.php?p=pos">نقطة البيع ←</a><a href="index.php?p=products">إدارة المنتجات ←</a><a href="index.php?p=sales">سجل المبيعات ←</a></div></section><?php end_page();exit;}
if($page==='products'){ $q=$pdo->prepare('SELECT p.*,COALESCE(i.quantity,0) stock FROM products p LEFT JOIN inventory i ON i.product_id=p.id AND i.branch_id=? WHERE p.workspace_id=? ORDER BY p.id DESC');$q->execute([$bid,$wid]);$rows=$q->fetchAll();start_page('المنتجات والمخزون');if($err||$msg):?><div class="alert"><?=h($err?:$msg)?></div><?php endif;?><div class="columns"><section class="card"><h2>إضافة منتج</h2><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><?php foreach(['name'=>'اسم المنتج','sku'=>'SKU','barcode'=>'الباركود','cost'=>'التكلفة','price'=>'سعر البيع','qty'=>'الرصيد الافتتاحي','alert_qty'=>'حد التنبيه'] as $k=>$v):?><label><?=$v?><input name="<?=$k?>" <?=$k==='name'||$k==='price'?'required':''?> <?=$k==='cost'||$k==='price'||$k==='qty'||$k==='alert_qty'?'type="number" min="0" step=".001"':''?>></label><?php endforeach;?><button class="btn">حفظ المنتج</button></form></section><section class="card tablebox"><h2>قائمة المنتجات</h2><table><tr><th>المنتج</th><th>السعر</th><th>المخزون</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['name'])?></td><td><?=cash($r['price'])?></td><td><?=h($r['stock'])?></td></tr><?php endforeach;?></table></section></div><?php end_page();exit;}
if($page==='pos'){ $q=$pdo->prepare('SELECT p.id,p.name,p.barcode,p.sku,p.price,COALESCE(i.quantity,0) stock FROM products p LEFT JOIN inventory i ON i.product_id=p.id AND i.branch_id=? WHERE p.workspace_id=? AND p.is_active=1 ORDER BY p.name');$q->execute([$bid,$wid]);$ps=$q->fetchAll();start_page('نقطة البيع');if($err||$msg):?><div class="alert"><?=h($err?:$msg)?></div><?php endif;?><section class="card"><input id="search" placeholder="ابحث بالاسم أو الباركود أو SKU"><div class="picker"><?php foreach($ps as $p):?><button type="button" class="tile" data-id="<?=$p['id']?>" data-name="<?=h($p['name'])?>" data-price="<?=$p['price']?>" data-stock="<?=$p['stock']?>" data-search="<?=h(strtolower($p['name'].' '.$p['barcode'].' '.$p['sku']))?>"><b><?=h($p['name'])?></b><span><?=cash($p['price'])?></span><small>المتاح: <?=$p['stock']?></small></button><?php endforeach;?></div><form method="post" id="saleForm"><input type="hidden" name="_token" value="<?=h(token())?>"><h2>السلة</h2><div class="tablebox"><table><thead><tr><th>المنتج</th><th>الكمية</th><th>السعر</th><th></th></tr></thead><tbody id="cart"><tr><td colspan="4">السلة فارغة</td></tr></tbody></table></div><div class="columns"><label>الخصم<input type="number" name="discount" min="0" step=".01" value="0"></label><label>طريقة الدفع<select name="method"><option value="cash">نقداً</option><option value="card">بطاقة</option><option value="transfer">تحويل</option></select></label></div><p class="total">الإجمالي: <b id="total">0.00</b></p><button class="btn">اعتماد البيع</button></form></section><?php end_page();exit;}
if($page==='sales'){ $q=$pdo->prepare('SELECT s.*,u.name cashier FROM sales s JOIN users u ON u.id=s.cashier_id WHERE s.workspace_id=? AND s.branch_id=? ORDER BY s.id DESC LIMIT 200');$q->execute([$wid,$bid]);$rs=$q->fetchAll();start_page('سجل المبيعات');?><section class="card tablebox"><table><tr><th>الفاتورة</th><th>التاريخ</th><th>الكاشير</th><th>الإجمالي</th><th>الدفع</th></tr><?php foreach($rs as $r):?><tr><td><?=h($r['invoice_no'])?></td><td><?=h($r['created_at'])?></td><td><?=h($r['cashier'])?></td><td><?=cash($r['total'])?></td><td><?=h($r['payment_method'])?></td></tr><?php endforeach;?></table></section><?php end_page();exit;}

if($page==='inventory'){if($_SERVER['REQUEST_METHOD']==='POST'){check_token();if(!manager())$err='لا تملك الصلاحية.';else{try{$pid=(int)$_POST['product_id'];$delta=(float)$_POST['delta'];if(!$delta)throw new Exception('أدخل فرقاً غير صفري.');$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,quantity FROM inventory WHERE workspace_id=? AND branch_id=? AND product_id=? FOR UPDATE');$q->execute([$wid,$bid,$pid]);$row=$q->fetch();if(!$row){if($delta<0)throw new Exception('لا يوجد رصيد لهذا المنتج.');$pdo->prepare('INSERT INTO inventory(workspace_id,branch_id,product_id,quantity) VALUES(?,?,?,?)')->execute([$wid,$bid,$pid,$delta]);}else{if((float)$row['quantity']+$delta<0)throw new Exception('التسوية ستجعل الرصيد سالباً.');$pdo->prepare('UPDATE inventory SET quantity=quantity+? WHERE id=?')->execute([$delta,$row['id']]);}$pdo->prepare("INSERT INTO inventory_movements(workspace_id,branch_id,product_id,user_id,movement_type,quantity,note) VALUES(?,?,?,?,'adjustment',?,?)")->execute([$wid,$bid,$pid,$u['id'],$delta,trim($_POST['note']??'تسوية يدوية')]);audit_event($pdo,'inventory.adjust','product',$pid);$pdo->commit();$msg='تم تسجيل التسوية.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}}}$q=$pdo->prepare('SELECT p.id,p.name,p.sku,p.barcode,p.cost,p.price,p.alert_qty,COALESCE(i.quantity,0) stock FROM products p LEFT JOIN inventory i ON i.product_id=p.id AND i.branch_id=? WHERE p.workspace_id=? ORDER BY p.name');$q->execute([$bid,$wid]);$rows=$q->fetchAll();start_page('إدارة المخزون');if($err||$msg):?><div class="alert"><?=h($err?:$msg)?></div><?php endif;?><section class="card"><h2>تسوية المخزون</h2><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><label>المنتج<select name="product_id"><?php foreach($rows as $r):?><option value="<?=$r['id']?>"><?=h($r['name'])?> — رصيد <?=h($r['stock'])?></option><?php endforeach;?></select></label><label>فرق الكمية (موجب إضافة / سالب خصم)<input type="number" step=".001" name="delta" required></label><label>سبب التسوية<input name="note"></label><button class="btn">اعتماد التسوية</button></form></section><section class="card tablebox"><h2>الأرصدة</h2><table><tr><th>المنتج</th><th>SKU</th><th>الرصيد</th><th>حد التنبيه</th><th>الحالة</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['sku'])?></td><td><?=h($r['stock'])?></td><td><?=h($r['alert_qty'])?></td><td><?=$r['stock']<=$r['alert_qty']?'منخفض':'متوفر'?></td></tr><?php endforeach;?></table></section><?php end_page();exit;}
if($page==='customers'||$page==='suppliers'){ $table=$page==='customers'?'customers':'suppliers';$title=$page==='customers'?'العملاء':'الموردون';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();if(!manager())$err='لا تملك الصلاحية.';else{$q=$pdo->prepare("INSERT INTO {$table}(workspace_id,name,phone,email,address) VALUES(?,?,?,?,?)");$q->execute([$wid,trim($_POST['name']),trim($_POST['phone']??''),trim($_POST['email']??''),trim($_POST['address']??'')]);audit_event($pdo,$page.'.create',$page,(int)$pdo->lastInsertId());$msg='تم الحفظ.';}}$q=$pdo->prepare("SELECT * FROM {$table} WHERE workspace_id=? ORDER BY id DESC LIMIT 500");$q->execute([$wid]);$rows=$q->fetchAll();start_page($title);if($err||$msg):?><div class="alert"><?=h($err?:$msg)?></div><?php endif;?><div class="columns"><section class="card"><h2>إضافة <?=$title==='العملاء'?'عميل':'مورد'?></h2><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><label>الاسم<input name="name" required></label><label>الهاتف<input name="phone"></label><label>البريد الإلكتروني<input type="email" name="email"></label><label>العنوان<input name="address"></label><button class="btn">حفظ</button></form></section><section class="card tablebox"><h2>القائمة</h2><table><tr><th>الاسم</th><th>الهاتف</th><th>البريد</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['phone'])?></td><td><?=h($r['email'])?></td></tr><?php endforeach;?></table></section></div><?php end_page();exit;}
if($page==='expenses'){if($_SERVER['REQUEST_METHOD']==='POST'){check_token();if(!manager())$err='لا تملك الصلاحية.';else{$amount=(float)$_POST['amount'];if($amount<=0)$err='المبلغ غير صحيح.';else{$q=$pdo->prepare('INSERT INTO expenses(workspace_id,branch_id,user_id,title,amount,expense_date) VALUES(?,?,?,?,?,?)');$q->execute([$wid,$bid,$u['id'],trim($_POST['title']),$amount,$_POST['expense_date']]);$msg='تم تسجيل المصروف.';audit_event($pdo,'expense.create','expense',(int)$pdo->lastInsertId());}}}$q=$pdo->prepare('SELECT * FROM expenses WHERE workspace_id=? AND branch_id=? ORDER BY expense_date DESC,id DESC LIMIT 200');$q->execute([$wid,$bid]);$rows=$q->fetchAll();start_page('المصروفات');if($err||$msg):?><div class="alert"><?=h($err?:$msg)?></div><?php endif;?><div class="columns"><section class="card"><h2>تسجيل مصروف</h2><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><label>البيان<input name="title" required></label><label>المبلغ<input type="number" name="amount" min=".01" step=".01" required></label><label>التاريخ<input type="date" name="expense_date" value="<?=date('Y-m-d')?>" required></label><button class="btn">حفظ المصروف</button></form></section><section class="card tablebox"><h2>السجل</h2><table><tr><th>التاريخ</th><th>البيان</th><th>المبلغ</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['expense_date'])?></td><td><?=h($r['title'])?></td><td><?=cash($r['amount'])?></td></tr><?php endforeach;?></table></section></div><?php end_page();exit;}
if($page==='reports'){ $from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$q=$pdo->prepare("SELECT COALESCE(SUM(total),0) sales,COALESCE(SUM(discount),0) discounts FROM sales WHERE workspace_id=? AND branch_id=? AND status='completed' AND DATE(created_at) BETWEEN ? AND ?");$q->execute([$wid,$bid,$from,$to]);$s=$q->fetch();$q=$pdo->prepare("SELECT COALESCE(SUM(si.quantity*si.unit_cost),0) cogs FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.workspace_id=? AND s.branch_id=? AND s.status='completed' AND DATE(s.created_at) BETWEEN ? AND ?");$q->execute([$wid,$bid,$from,$to]);$cogs=(float)$q->fetchColumn();$q=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE workspace_id=? AND branch_id=? AND expense_date BETWEEN ? AND ?');$q->execute([$wid,$bid,$from,$to]);$ex=(float)$q->fetchColumn();$q=$pdo->prepare('SELECT p.name,SUM(si.quantity) qty,SUM(si.line_total) total FROM sale_items si JOIN sales s ON s.id=si.sale_id JOIN products p ON p.id=si.product_id WHERE s.workspace_id=? AND s.branch_id=? AND s.status=\'completed\' AND DATE(s.created_at) BETWEEN ? AND ? GROUP BY p.id,p.name ORDER BY qty DESC LIMIT 10');$q->execute([$wid,$bid,$from,$to]);$tops=$q->fetchAll();start_page('التقارير');?><section class="card"><form method="get"><input type="hidden" name="p" value="reports"><div class="columns"><label>من تاريخ<input type="date" name="from" value="<?=h($from)?>"></label><label>إلى تاريخ<input type="date" name="to" value="<?=h($to)?>"></label></div><button class="btn">تحديث التقرير</button><button type="button" class="btn" onclick="window.print()">طباعة</button></form></section><section class="stats"><article><span>صافي المبيعات</span><b><?=cash($s['sales'])?></b></article><article><span>تكلفة البضاعة</span><b><?=cash($cogs)?></b></article><article><span>مجمل الربح</span><b><?=cash((float)$s['sales']-$cogs)?></b></article><article><span>المصروفات</span><b><?=cash($ex)?></b></article><article><span>الربح التشغيلي التقديري</span><b><?=cash((float)$s['sales']-$cogs-$ex)?></b></article></section><section class="card tablebox"><h2>الأكثر مبيعاً</h2><table><tr><th>المنتج</th><th>الكمية</th><th>قيمة البيع</th></tr><?php foreach($tops as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['qty'])?></td><td><?=cash($r['total'])?></td></tr><?php endforeach;?></table><p class="muted">الأرباح تقديرية وفق تكلفة المنتج المسجلة عند البيع، ولا تشمل الضرائب أو تكاليف التشغيل الأخرى.</p></section><?php end_page();exit;}
if($page==='branches'){if($_SERVER['REQUEST_METHOD']==='POST'){check_token();if(!manager())$err='لا تملك الصلاحية.';else{$name=trim($_POST['name']);$code=strtoupper(trim($_POST['code']));if($name&&$code){try{$q=$pdo->prepare('INSERT INTO branches(workspace_id,name,code) VALUES(?,?,?)');$q->execute([$wid,$name,$code]);$msg='تم إنشاء الفرع.';}catch(Throwable $e){$err='تعذر إنشاء الفرع؛ تحقق من عدم تكرار الرمز.';}}}}$q=$pdo->prepare('SELECT * FROM branches WHERE workspace_id=? ORDER BY id');$q->execute([$wid]);$rows=$q->fetchAll();start_page('إدارة الفروع');if($err||$msg):?><div class="alert"><?=h($err?:$msg)?></div><?php endif;?><section class="card"><h2>إضافة فرع</h2><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><label>اسم الفرع<input name="name" required></label><label>رمز الفرع<input name="code" required></label><button class="btn">إضافة</button></form></section><section class="card"><h2>الفروع</h2><?php foreach($rows as $r):?><p><?=h($r['name'])?> — <?=h($r['code'])?> <?=((int)$r['id']===$bid?' (الفرع الحالي)':'')?></p><?php endforeach;?></section><?php end_page();exit;}
if($page==='users'){if($_SERVER['REQUEST_METHOD']==='POST'){check_token();if(!in_array($u['role'],['owner','system_admin'],true))$err='إنشاء المستخدمين متاح للمالك فقط.';else{try{$branch=(int)$_POST['branch_id'];$q=$pdo->prepare('SELECT id FROM branches WHERE id=? AND workspace_id=?');$q->execute([$branch,$wid]);if(!$q->fetchColumn())throw new Exception('الفرع غير صحيح.');$allowedRoles=($u['role']==='owner'||$u['role']==='system_admin')?['system_admin','manager','supervisor','cashier']:['supervisor','cashier'];$role=in_array($_POST['role'],$allowedRoles,true)?$_POST['role']:'cashier';$q=$pdo->prepare('INSERT INTO users(workspace_id,branch_id,name,username,password_hash,role) VALUES(?,?,?,?,?,?)');$q->execute([$wid,$branch,trim($_POST['name']),trim($_POST['username']),password_hash($_POST['password'],PASSWORD_DEFAULT),$role]);$msg='تم إنشاء المستخدم.';}catch(Throwable $e){$err='تعذر إنشاء المستخدم؛ تحقق من اسم المستخدم وكلمة المرور.';}}}$q=$pdo->prepare('SELECT id,name,code FROM branches WHERE workspace_id=?');$q->execute([$wid]);$branches=$q->fetchAll();$q=$pdo->prepare('SELECT u.id,u.name,u.username,u.role,u.status,b.name branch FROM users u LEFT JOIN branches b ON b.id=u.branch_id WHERE u.workspace_id=? ORDER BY u.id');$q->execute([$wid]);$rows=$q->fetchAll();start_page('المستخدمون والصلاحيات');if($err||$msg):?><div class="alert"><?=h($err?:$msg)?></div><?php endif;?><section class="card"><h2>مستخدم جديد</h2><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><label>الاسم<input name="name" required></label><label>اسم المستخدم<input name="username" minlength="3" required></label><label>كلمة المرور<input type="password" name="password" minlength="10" required></label><label>الفرع<select name="branch_id"><?php foreach($branches as $b):?><option value="<?=$b['id']?>"><?=h($b['name'])?></option><?php endforeach;?></select></label><label>الدور<select name="role"><?php if(in_array($u['role'],['owner','system_admin'],true)):?><option value="system_admin">مدير النظام</option><?php endif;?><option value="cashier">كاشير</option><option value="supervisor">مشرف</option><option value="manager">مدير</option></select></label><button class="btn">إنشاء المستخدم</button></form></section><section class="card tablebox"><table><tr><th>الاسم</th><th>اسم المستخدم</th><th>الدور</th><th>الفرع</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['username'])?></td><td><?=h($r['role'])?></td><td><?=h($r['branch'])?></td></tr><?php endforeach;?></table></section><?php end_page();exit;}
